/**
 * A corpus of `v8.serialize` inputs, shared by the oracle generator and the
 * parity test.
 *
 * `tools/v8-corpus-oracle.mjs` runs this through a real Node and writes
 * `test/fixtures/v8-corpus.json`; `test/v8-corpus.test.ts` runs the identical
 * list through the web-node runtime and asserts the bytes are equal. Keeping
 * one list means neither side can drift.
 *
 * Values must be deterministic and stack-free so both engines produce
 * identical bytes.
 */
export function corpus() {
  const shared = { v: 1 };
  const selfRef = {};
  selfRef.self = selfRef;
  const selfCause = new Error('m');
  selfCause.stack = 'ST';
  selfCause.cause = selfCause;

  const denseHole = [1, , 3];
  const arrayWithProps = Object.assign([1, 2], { x: 9 });

  return [
    ['undefined', undefined],
    ['null', null],
    ['true', true],
    ['false', false],
    ['zero', 0],
    ['one', 1],
    ['negOne', -1],
    ['i32max', 2147483647],
    ['i32min', -2147483648],
    ['aboveI32max', 2147483648],
    ['u32max', 4294967295],
    ['aboveU32max', 4294967296],
    ['i53max', 9007199254740991],
    ['i53over', 9007199254740992],
    ['double', 1.5],
    ['negDouble', -1.5],
    ['negZero', -0],
    ['tiny', 1e-300],
    ['huge', 1e300],
    ['nan', NaN],
    ['infinity', Infinity],
    ['negInfinity', -Infinity],
    ['wholeDouble', 100],
    ['bigint0', 0n],
    ['bigint1', 1n],
    ['bigintNeg1', -1n],
    ['bigint255', 255n],
    ['bigint2pow64', 2n ** 64n],
    ['bigint2pow64minus1', 2n ** 64n - 1n],
    ['bigintHuge', 123456789012345678901234567890n],
    ['bigintNegHuge', -123456789012345678901234567890n],
    ['stringEmpty', ''],
    ['stringAscii', 'abc'],
    ['stringLatin1', 'héllo'],
    ['stringLatin1Max', '\u00ff'],
    ['stringTwoByte', '\u0100'],
    ['stringCjk', '中文'],
    ['stringEmoji', '🦀'],
    ['stringLoneSurrogate', '\ud800'],
    ['stringLong', 'x'.repeat(300)],
    ['stringLongTwoByte', '中'.repeat(200)],
    ['objectEmpty', {}],
    ['objectSimple', { a: 1 }],
    ['objectNested', { a: { b: [1, 2] } }],
    ['objectUndefinedValue', { a: undefined }],
    ['objectNullOrUndefinedKey', { a: null, b: undefined }],
    ['objectIntKeys', { 2: 'b', 1: 'a' }],
    ['objectMixedKeys', { 1: 'a', z: 'b' }],
    ['objectGetter', { get x() { return 42; } }],
    ['objectNullProto', Object.assign(Object.create(null), { a: 1 })],
    ['objectFrozen', Object.freeze({ a: 1 })],
    ['objectShared', { a: shared, b: shared }],
    ['objectSelfRef', selfRef],
    ['arrayEmpty', []],
    ['arraySmi', [1, 2, 3]],
    ['arrayDouble', [1.5, 2]],
    ['arrayDoubleAll', [1.5, 2.5]],
    ['arrayPushedDouble', [2147483647, 2147483648]],
    ['arrayNegZero', [-0]],
    ['arrayMixed', [1, 'a']],
    ['arrayBoxed', [new Number(1), new String('a'), new Boolean(true)]],
    ['arrayHole', [1, , 3]],
    ['arrayHoleTail', [1, ,]],
    ['arrayProps', arrayWithProps],
    ['arrayNested', [[1], { a: 2 }]],
    ['arrayHoleZero', [, 1]],
    ['dateEpoch', new Date(0)],
    ['dateLater', new Date(1700000000123)],
    ['dateInvalid', new Date(NaN)],
    ['regexpNone', /ab+c/],
    ['regexpGi', /ab+c/gi],
    ['regexpU', /x/u],
    ['regexpD', /x/d],
    ['regexpDgsuy', /x/dgsuy],
    ['regexpV', /x/v],
    ['mapSimple', new Map([[1, 'a'], ['b', 2]])],
    ['mapNested', new Map([[new Map([['k', 'v']]), new Set([1])]])],
    ['mapSelf', (() => { const m = new Map(); m.set('self', m); return m; })()],
    ['setSimple', new Set([1, 2, 'x'])],
    ['setObjects', new Set([{ a: 1 }, { a: 1 }])],
    ['boxedTrue', new Boolean(true)],
    ['boxedFalse', new Boolean(false)],
    ['boxedNumber', new Number(42)],
    ['boxedString', new String('s')],
    ['boxedBigint', Object(7n)],
    ['errorPlain', (() => { const e = new Error('boom'); e.stack = 'STACK'; return e; })()],
    ['errorType', (() => { const e = new TypeError(''); e.stack = 'S'; return e; })()],
    ['errorRange', (() => { const e = new RangeError('r'); e.stack = 'S'; return e; })()],
    ['errorRef', (() => { const e = new ReferenceError('r'); e.stack = 'S'; return e; })()],
    ['errorSyntax', (() => { const e = new SyntaxError('s'); e.stack = 'S'; return e; })()],
    ['errorUri', (() => { const e = new URIError('u'); e.stack = 'S'; return e; })()],
    ['errorEval', (() => { const e = new EvalError('e'); e.stack = 'S'; return e; })()],
    ['errorNoStack', (() => { const e = new Error('m'); e.stack = undefined; return e; })()],
    ['errorCause', (() => { const e = new Error('m'); e.stack = 'S'; e.cause = 'because'; return e; })()],
    ['errorSelfCause', selfCause],
    ['errorExtraProps', (() => { const e = new Error('c'); e.stack = 'S'; e.code = 'E1'; return e; })()],
    ['arrayBufferEmpty', new ArrayBuffer(0)],
    ['arrayBuffer', new ArrayBuffer(4)],
    ['arrayBuffer300', new ArrayBuffer(300)],
    ['viewInt8', new Int8Array([1, 2, 3])],
    ['viewUint8', new Uint8Array([1, 2, 3, 4])],
    ['viewClamped', new Uint8ClampedArray([1, 2])],
    ['viewInt16', new Int16Array([1, -2])],
    ['viewUint16', new Uint16Array([1, 2])],
    ['viewInt32', new Int32Array([1, 2])],
    ['viewUint32', new Uint32Array([1, 2])],
    ['viewFloat32', new Float32Array([1.5])],
    ['viewFloat64', new Float64Array([1.5])],
    ['viewBigInt64', new BigInt64Array([1n])],
    ['viewBigUint64', new BigUint64Array([1n])],
    ['viewDataView', new DataView(new ArrayBuffer(8), 2, 4)],
    ['viewEmpty', new Uint8Array(0)],
    ['viewShared', { a: new Uint8Array([1, 2]), b: [1, 2, 3] }],
    ['deepNesting', { a: { b: { c: { d: [1, [2, [3]]] } } } }],
    ['denseHole', denseHole],
  ];
}
